/* draft-review 前端：原生 JS，无构建 */
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];

const state = {
  doc: null,
  notes: [],
  filter: "open",
  tags: [],
  draft: null,
  mode: "all",     // all | focus
  cur: 1,          // 逐段模式的当前段
  read: new Set(), // 已读段落号（本机）
  review: {},      // 段落审核状态（服务端 review.json）：{para: {state:"done"|"stale", at}}
  changes: [],     // 没有批注托着的改动（服务端 changes.json），页面上按 after 标出
  showCtx: false,
};
const TAGS = ["数字", "术语", "结构", "文字", "越界", "删"];
const docEl = $("#doc");
const marginEl = $("#margin");
const pillEl = $("#pill");

/* ------------------------------------------------------------ 已读 / 地图 */
function readKey() {
  // 按文稿路径记，改稿后 hash 变了也不丢"已读"进度
  return `wmn:read:${state.doc?.path || "x"}`;
}
function loadRead() {
  try {
    state.read = new Set(JSON.parse(localStorage.getItem(readKey()) || "[]"));
  } catch {
    state.read = new Set();
  }
}
function saveRead() {
  localStorage.setItem(readKey(), JSON.stringify([...state.read]));
}
function markRead(i, val = true) {
  if (!i) return;
  if (val) state.read.add(i);
  else state.read.delete(i);
  saveRead();
  renderMap();
}

function isReviewed(i) { return state.review[i]?.state === "done"; }
function firstUnreviewed(list) { return list.find((p) => !isReviewed(p.i)); }
function isStale(i) { return state.review[i]?.state === "stale"; }

async function toggleReview(i) {
  if (!i) return;
  const done = !isReviewed(i);
  try {
    await api(`/api/review/${i}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ done }),
    });
  } catch (err) {
    return toast("标记失败：" + err.message, 4000);   // 失败不改本地状态，按钮保持原样
  }
  if (done) state.review[i] = { state: "done", at: new Date().toISOString() };
  else delete state.review[i];
  renderMap();
  const el = $(`.para[data-i="${i}"]`, docEl);
  if (el) {
    el.classList.toggle("rev", done);
    el.classList.toggle("revstale", !done && isStale(i));
  }
  syncDoneBtn();
  toast(done ? `P${i} 已审` : `P${i} 取消已审`);
}

/* 全文模式没有"当前段"：取第一个还露在视口里的段（顶部对齐阅读位置） */
function paraAtViewport() {
  const items = $$(".para", docEl).map((el) => {
    const r = el.getBoundingClientRect();
    return { el, top: r.top, bottom: r.bottom };
  });
  if (!items.length) return 0;
  const pick = items.find((x) => x.bottom > 90) || items[items.length - 1];
  return +pick.el.dataset.i || 0;
}

function currentPara() {
  return state.mode === "focus" ? state.cur : paraAtViewport();
}


function syncDoneBtn() {
  const b = $("#f-done");
  if (!b) return;
  const i = currentPara();
  const on = i ? isReviewed(i) : false;
  const stale = i ? isStale(i) : false;
  b.classList.toggle("on", on);
  b.classList.toggle("stale", stale);
  b.textContent = on ? "☑ 已审" : stale ? "↻ 本节改过，重标审完" : "☐ 审完本段";
  b.title = on ? "再点一次撤销（m）" : "把这一段标为审完，之后可跳过（m）";
}

function noteCount(i) {
  return state.notes.filter((n) => n.para_anchor === i).length;
}

function renderMap() {
  const map = $("#map");
  const mapinfo = $("#mapinfo");
  map.innerHTML = "";
  const cntBy = new Map(), fixedBy = new Set();
  for (const n of state.notes) {
    cntBy.set(n.para_anchor, (cntBy.get(n.para_anchor) || 0) + 1);
    if (n.status === "done" && n.reply) fixedBy.add(n.para_anchor);
  }
  for (const p of state.doc.paras) {
    const b = document.createElement("button");
    b.className = "cell";
    b.textContent = p.i;
    const cnt = cntBy.get(p.i) || 0;
    b.title = `P${p.i}　${p.text.slice(0, 24)}…` + (cnt ? `（${cnt} 条批注）` : "")
      + (isReviewed(p.i) ? "　已审" : isStale(p.i) ? "　需重审" : "");
    if (cnt) b.classList.add("has");
    if (fixedBy.has(p.i)) b.classList.add("fixed");
    if (state.read.has(p.i)) b.classList.add("read");
    b.classList.toggle("todo", fixedBy.has(p.i) && !isReviewed(p.i));
    if (isReviewed(p.i)) b.classList.add("rev");
    else if (isStale(p.i)) b.classList.add("revstale");
    if (state.mode === "focus" && p.i === state.cur) b.classList.add("cur");
    b.onclick = () => gotoPara(p.i);
    map.appendChild(b);
  }
  const total = state.doc.paras.length;
  const read = state.doc.paras.filter((p) => state.read.has(p.i)).length;   // 段删掉后不虚增
  const fixed = state.notes.filter((n) => n.status === "done" && n.reply).length;
  const open = state.notes.filter((n) => n.status === "open" && n.anchor !== "orphan").length;
  const orphan = state.notes.filter((n) => n.anchor === "orphan").length;
  const rev = state.doc.paras.filter((p) => isReviewed(p.i)).length;
  const stale = state.doc.paras.filter((p) => isStale(p.i)).length;
  // 统计行：两段进度与批注计数用竖线隔开，数字加粗，全宽一行放在地图下
  mapinfo.innerHTML =
    `<span>已读 <b>${read}/${total}</b></span>`
    + `<span>已审 <b>${rev}/${total}</b>${stale ? `<span class="stale">（过期 ${stale}）</span>` : ""}</span>`
    + `<span class="sep"></span>`
    + `<span>待处理 <b>${open}</b></span>`
    + `<span>已改 <b>${fixed}</b></span>`
    + (orphan ? `<span>失效 <b>${orphan}</b></span>` : "");
}

/* 顶栏会换行，高度随窗口变；地图栏的 sticky 位置要跟着顶栏实际高度走 */
function syncStickyTop() {
  const tb = document.querySelector(".topbar");
  if (tb) document.documentElement.style.setProperty("--toph", tb.offsetHeight + "px");
}

function gotoPara(i, opts = {}) {
  const total = state.doc.paras.length;
  i = Math.min(total, Math.max(1, i));
  if (state.mode === "focus" && opts.markRead !== false && state.cur !== i) markRead(state.cur);
  state.cur = i;
  if (state.mode !== "focus") {
    const el = $(`.para[data-i="${i}"]`, docEl);
    if (el) el.scrollIntoView({ block: "center", behavior: "smooth" });
    markRead(i);
    renderMap();
    return;
  }
  renderDoc();
  renderCards();
  renderMap();
  $("#f-pos").textContent = `P${i} / ${total}`;
  syncDoneBtn();
  markRead(i);
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function applyModeChrome() {
  const focus = state.mode === "focus";
  document.body.classList.toggle("focus-mode", focus);
  docEl.classList.toggle("focus", focus);
  $("#focusbar").hidden = !focus;
  $("#btn-mode").textContent = focus ? "全文" : "逐段";
  $("#f-pos").textContent = `P${state.cur} / ${state.doc.paras.length}`;
  syncDoneBtn();
}

function setMode(mode) {
  state.mode = mode;
  localStorage.setItem("wmn:mode", mode);
  if (mode === "focus") {
    const exists = state.doc.paras.some((p) => p.i === state.cur);
    if (!exists) {
      // 优先落到第一个没标「已改」的段，其次才是未读段
      const first = firstUnreviewed(state.doc.paras)
        || state.doc.paras.find((p) => !state.read.has(p.i));
      state.cur = first ? first.i : 1;
    }
  }
  applyModeChrome();
  renderDoc();
  renderCards();
  renderMap();
}

/* ------------------------------------------------------------ 工具 */
async function api(url, opt) {
  const r = await fetch(url, opt);
  if (!r.ok) throw new Error((await r.json().catch(() => ({}))).error || r.statusText);
  return r.json();
}
function toast(msg, ms = 2200) {
  const t = $("#toast");
  t.textContent = msg;
  t.hidden = false;
  clearTimeout(t._t);
  t._t = setTimeout(() => (t.hidden = true), ms);
}
/* 引文是整段公式时别把 TeX 原样塞进卡片 */
function quoteLabel(q) {
  const t = (q || "").trim();
  if (/^\$\$[\s\S]*\$\$$/.test(t)) return "［公式］";
  let s = t.length > 90 ? t.slice(0, 90) + "…" : t;
  if (((s.match(/\$/g) || []).length) % 2) s = s.slice(0, s.lastIndexOf("$")) + "…";  // 别把 $…$ 截断
  return s;
}

function esc(s) {
  return s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

/* markdown 表格转 <table>；纯展示，选区偏移按原 text 反查 */
function tableEl(text) {
  const rows = text.split("\n").filter((l) => l.trim().startsWith("|"));
  const cells = (l) => l.trim().replace(/^\|/, "").replace(/\|$/, "").split("|").map((c) => c.trim());
  const t = document.createElement("table");
  t.className = "mdtable";
  rows.forEach((line) => {
    if (/^[\s:|-]+$/.test(line.trim().replace(/^\|/, "").replace(/\|$/, ""))) return;
    const tr = document.createElement("tr");
    for (const c of cells(line)) {
      const td = document.createElement(t.querySelector("tr") ? "td" : "th");
      td.textContent = c;
      tr.appendChild(td);
    }
    t.appendChild(tr);
  });
  return t;
}

/* ------------------------------------------------------------ 行内批注 */
/* 批注卡片紧跟在「被批注那句」的下一行，不再放到右侧边注列 */
function sentenceEnd(text, pos) {
  const re = /[。！？；\n]/g;
  re.lastIndex = Math.max(0, pos - 1);
  const r = re.exec(text);
  return r ? r.index + 1 : text.length;
}

/* 卡片插哪：优先贴着最近的逗号/顿号/分号（离被批注的词最近），
   整句内没有分隔符时才退到句末。 */
function cutPoint(text, pos) {
  const end = sentenceEnd(text, pos);
  const re = /[，、；：]/g;
  re.lastIndex = Math.max(0, pos);
  const m = re.exec(text);
  return m && m.index < end ? m.index + 1 : end;
}

function renderSeg(text, bold, marks, from, to) {
  const seg = text.slice(from, to);
  const bs = bold
    .map(([a, b]) => [Math.max(0, a - from), Math.min(seg.length, b - from)])
    .filter(([a, b]) => b > a);
  const ms = marks
    .filter((m) => m.e > from && m.s < to)      // 只留与本切片真正重叠的，别把前半段的标记拽到段首
    .map((m) => ({ ...m, s: Math.max(0, m.s - from), e: Math.min(seg.length, m.e - from) }))
    .filter((m) => m.e > m.s);
  return renderRich(seg, bs, ms);
}

function inlineCard(n) {
  const c = cardEl(n);
  c.classList.add("inline");
  return c;
}

/* 整段只有行间公式（$$…$$）时，交给 KaTeX 画；原文放进隐藏的 .ptext，
   锚点仍按原字符偏移计算，只是这一段不能划词（用段号提整段意见）。 */
function isDisplayMath(text) {
  if (!/\$\$[\s\S]+?\$\$/.test(text)) return false;
  return text.replace(/\$\$[\s\S]+?\$\$/g, "").trim() === "";   // 去掉公式后没有别的字
}

/* 行内 $…$ 就地渲染；只画成 HTML，避免 MathML 副本把选区文本翻倍 */
function renderMathIn(el) {
  if (!window.renderMathInElement || !el.textContent.includes("$")) return;
  try {
    window.renderMathInElement(el, {
      delimiters: [{ left: "$$", right: "$$", display: true },
                   { left: "$", right: "$", display: false }],
      throwOnError: false,
      output: "html",
    });
  } catch (e) { /* 保留原文 */ }
}

function mathBox(text) {
  const box = document.createElement("div");
  box.className = "mathbox";
  box.textContent = text;
  const paint = () => {
    if (window.renderMathInElement) {
      try {
        window.renderMathInElement(box, {
          delimiters: [{ left: "$$", right: "$$", display: true },
                       { left: "$", right: "$", display: false }],
          throwOnError: false,
        });
      } catch (e) { /* 渲染失败就保留原文 */ }
    }
  };
  paint();
  return box;
}

/* ------------------------------------------------------------ 渲染正文 */
function renderRich(text, bold, marks) {
  const cuts = new Set([0, text.length]);
  for (const [s, e] of bold) { cuts.add(s); cuts.add(e); }
  for (const m of marks) { cuts.add(m.s); cuts.add(m.e); }
  const pts = [...cuts].sort((a, b) => a - b);
  const frag = document.createDocumentFragment();
  for (let i = 0; i < pts.length - 1; i++) {
    const s = pts[i], e = pts[i + 1];
    if (e <= s) continue;
    let node = document.createTextNode(text.slice(s, e));
    // 允许区间重叠：外层先包（范围大的在外），内层后包，两条批注都能点
    // 嵌套时最内层画在最上面：小范围先包（成为子元素），大范围后包（成为父元素）。
    // 同范围时 open 优先，保证新加的黄批注不会被旧的绿批注盖住。
    const covering = marks
      .filter((m) => s >= m.s && e <= m.e)
      .sort((a, b) =>
        (a.e - a.s) - (b.e - b.s) ||
        ((a.status === "done" ? 1 : 0) - (b.status === "done" ? 1 : 0)));
    for (const mk of covering) {
      const el = document.createElement("mark");
      el.className = "hl" + (mk.anchor === "fuzzy" ? " fuzzy" : "")
        + (mk.status === "done" ? " done" : "") + (mk.status === "chg" ? " chg" : "");
      el.dataset.id = mk.id;
      el.title = mk.text || "";
      el.appendChild(node);
      node = el;
    }
    if (bold.some(([a, b]) => s >= a && e <= b)) {
      const st = document.createElement("strong");
      st.appendChild(node);
      node = st;
    }
    frag.appendChild(node);
  }
  return frag;
}

/* 高亮用的批注集合：当前筛选内的 + 「已改但这段还没审完」的。
   后者不看筛选，保证作者总能顺着颜色找到刚改过的句子。 */
function markNotes(p) {
  return state.notes.filter((n) => {
    if (n.para_anchor !== p.i || !n.quote_anchor || n.anchor === "orphan") return false;
    if (visible(n)) return true;
    return n.status === "done" && n.hl && !isReviewed(p.i);
  });
}

/* 没有批注托着的改动（统一用词、去口头语等）：按 after 在段内标出，
   段落下方再列一行「改前 → 改后」，作者既能看到改在哪，也能核对改成什么。 */
function changeMarks(p) {
  const out = [];
  for (const c of state.changes || []) {
    if (c.para !== p.i || !c.after) continue;
    const i = p.text.indexOf(c.after);
    if (i < 0) continue;
    out.push({
      id: c.id, s: i, e: i + c.after.length, anchor: "exact", status: "chg",
      text: `第${c.round || "?"}轮改前：${c.before || "—"}`,
      before: c.before, after: c.after, round: c.round, why: c.why,
    });
  }
  return out;
}

function changeLine(p) {
  const list = (state.changes || []).filter((c) => c.para === p.i && c.after);
  if (!list.length) return null;
  const box = document.createElement("div");
  box.className = "chgline";
  for (const c of list) {
    const row = document.createElement("div");
    row.className = "chgrow";
    row.innerHTML = `<span class="chgwho">第 ${c.round || "?"} 轮</span>`
      + `<s>${esc(c.before || "—")}</s><span class="arrow">→</span><b>${esc(c.after)}</b>`
      + (c.why ? `<span class="chgwhy">（${esc(c.why)}）</span>` : "");
    box.appendChild(row);
  }
  return box;
}

function highlightFragment(text, paraNo, bold) {
  const p = state.doc.paras[paraNo - 1] || { i: paraNo, text };
  const marks = markNotes(p)
    .map((n) => ({ n, s: n.offset, e: n.offset + n.quote_anchor.length }))
    .filter((x) => x.s >= 0 && x.e <= text.length && x.e > x.s)
    .sort((a, b) => a.s - b.s);
  const noteMarks = marks.map((m) => ({
    ...m, id: m.n.id, anchor: m.n.anchor, status: m.n.status, text: m.n.text,
  }));
  return renderRich(text, bold || [], noteMarks.concat(changeMarks(p)));
}

